  ('KIM-0084', 'Üzvi kimya', 'Aldehidlər və ketonlar', 'aciq_eded', '3,3-dimetilbutanal molekulunda funksional qrupun kütlə payını (%-lə) hesablayın. $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(H)=1,}$ $\mathrm{A_{r}(O)=16}$', NULL::text, NULL::text, '29', '3', '3,3-dimetilbutanalın kimyəvi formulu $\mathrm{C_{6}H_{12}O,}$ 1 molunun kütləsi 100 qramdır. Tərkibində olan $\mathrm{CHO}$ funksional qrupunun kütləsinin 29 qram olduğunu nəzərə alsaq, bu funksional qrupun kütlə payı 29% təşkil edir.', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №54'),
  ('KIM-0086', 'Qeyri-üzvi kimya', 'Karbon və silisium', 'aciq_eded', 'Termiki parçalanmaya davamlı 25% kənar qarışıq saxlayan əhəngdaşının tərkibindəki $\mathrm{CaCO_{3}}$-ün tam parçalanmasından 134 qram bərk qalıq alınmışdır. Parçalanma zamanı alınan karbon qazının həcmini (litr, n.ş.) hesablayın. $\mathrm{A_{r}(Ca)=40,}$ $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(O)=16}$', NULL::text, NULL::text, '33,6', '3', 'Əhəng daşının kütləsini x qram götürüb, hesablamaları aparaq 0,75x a $\mathrm{CaCO_{3}}$ t → $\mathrm{CaO + CO_{2}}$ 100 56 a= 0,42x q $\mathrm{CaO}$ 0,25x + 0,42x =134 x=200 0,75⋅200 b $\mathrm{CaCO_{3}}$ t → $\mathrm{CaO + CO_{2}}$ 100 22,4 b =33,6', '{4}', '2025', '2025-07-13 qəbul, IV qrup, A variantı №56'),
  ('KIM-0092', 'Ümumi kimya', 'Oksidləşmə-reduksiya reaksiyaları', 'qapali', '$\mathrm{KOH + Cl_{2}}$ t → $\mathrm{KCl + KClO_{3}+}$ $\mathrm{H_{2}O}$ reaksiyası üçün nə doğrudur? 1. $\mathrm{Cl_{2}}$ həm oksidləşdirici, həm də reduksiyaedicidir 2. $\mathrm{KCl}$ oksidləşmə məhsuludur 3. $\mathrm{KClO_{3}}$ reduksiyaedicidir', NULL::text, '{"A": "1, 3", "B": "yalnız 3", "C": "yalnız 2", "D": "yalnız 1", "E": "1, 2"}', 'D', '3', '$\mathrm{KOH + Cl_{2}}$ t → $\mathrm{KCl + KClO_{3} + H_{2}O}$ 0 -1 +5 Oksidləşmə dərəcəsinin dəyişməsinə görə $\mathrm{Cl_{2}}$ həm oksidləşdirici, həm də reduksiyaedicidir, $\mathrm{KCl}$ reduksiya məhsuludur, $\mathrm{KClO_{3}}$ oksidləşmə məhsuludur.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №62'),
  ('KIM-0098', 'Ümumi kimya', 'Elektrolitik dissosiasiya və ion mübadiləsi', 'qapali', 'I. $\mathrm{CH_{3}COOH}$ və $\mathrm{NaOH}$ II. $\mathrm{Ba(OH)_{2},}$ $\mathrm{HCl}$ və $\mathrm{HNO_{3}}$ III. $\mathrm{HCl}$ və $\mathrm{KOH}$ Eyni həcmli və eyni molyar qatılıqlı verilmiş maddələrin məhlullarının qarışıqlarının hansılarında mühit neytraldır?', NULL::text, '{"A": "yalnız I", "B": "yalnız III", "C": "yalnız II", "D": "I, II, III", "E": "II, III"}', 'E', '3', 'I. $\mathrm{CH_{3}COOH + NaOH \rightarrow H_{2}O + CH_{3}COONa}$ (mühit qələvi) II $\mathrm{Ba(OH)_{2} + HCl + HNO_{3} \rightarrow BaCl(NO_{3}) + H_{2}O}$ (mühit neytral) III. $\mathrm{HCl + KOH \rightarrow KCl+H_{2}O}$ (mühit neytral)', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №68'),
  ('KIM-0099', 'Ümumi kimya', 'Reaksiyaların təsnifatı və istilik effekti', 'qapali', '$\mathrm{2H_{2}(q)+O_{2}(q)=2H_{2}O(m)+572}$ kC Termokimyəvi tənliyi üçün hansı ifadələr doğrudur? 1. Suyun əmələgəlmə istiliyi +286 kC/mol-dur 2. Reaksiyanın istilik effekti +286 kC-dur 3. Hidrogenin yanma istiliyi +286 kC/mol-dur 4. Suyun parçalanma reaksiyasının istilik effekti +572 kC-dur', NULL::text, '{"A": "2, 4", "B": "1, 3", "C": "2, 3", "D": "3, 4", "E": "1, 2, 3"}', 'B', '3', 'Verilmiş termokimyəvi tənliyə uyğun olaraq 1. Suyun əmələgəlmə istiliyi 572:2= +286 kC/mol-dur 2. Reaksiyanın istilik effekti 572 kC-dur 3. Hidrogenin yanma istiliyi 572:2= +286 kC/mol-dur 4. Suyun parçalanma reaksiyasının istilik effekti - 572 kC-dur', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №69'),
  ('KIM-0100', 'Qeyri-üzvi kimya', 'Kükürd və birləşmələri', 'qapali', '$\mathrm{Fe_{2}(SO_{4})_{3}}$ t → $\mathrm{Fe_{2}O_{3}+X}$ Hansı ifadə doğrudur?', NULL::text, '{"A": "reaksiya oksidləşmə-reduksiya reaksiyasıdır", "B": "X – $\\mathrm{SO_{2}}$-dir", "C": "X – sulfat turşusudur", "D": "kükürd atomu reduksiyaedicidir", "E": "X qələvilərlə reaksiyaya daxil olur"}', 'E', '3', 'Dəmir(III)sulfatın parçalanma reaksiyası: $\mathrm{Fe_{2}(SO_{4})_{3}}$ t → $\mathrm{Fe_{2}O_{3}+}$ $\mathrm{SO_{3}}$ kimidir. Reaksiya tənliyindən aydın olur ki, X maddəsi $\mathrm{SO_{3}}$-dür. $\mathrm{SO_{3}}$ turşu oksidi olduğu üçün qələvilərlə reaksiyaya daxil olur.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №70'),
  ('KIM-0106', 'Ümumi kimya', 'Məhlullar', 'qapali', '20%-li doymamış məhlul hazırlamaq üçün 40 q duzu neçə qram suda həll etmək lazımdır?', NULL::text, '{"A": "210", "B": "160", "C": "120", "D": "80", "E": "100"}', 'B', '3', 'Məsələnin şərtinə əsasən 40 q duz suda həll edildikdə 20% məhlul alınmışdır. Deməli bu məhlulun kütləcə 20 % duz 80 % isə sudur. Uyğun hesablama aparsaq 20%---------------40 q 80%-----------------x q x=160', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №76'),
  ('KIM-0110', 'Üzvi kimya', 'Yüksək molekullu birləşmələr', 'qapali', 'Mürəkkəb efirlərə aid olan irimolekullu birləşməni göstərin.', NULL::text, '{"A": "sellüloza", "B": "kapron", "C": "təbii kauçuk", "D": "lavsan", "E": "polivinilxlorid"}', 'D', '3', 'Verilmiş iri molekullu birləşmələrdən yalnız lavsan efirləşmə reaksiyasından alınır. Lavsan makromolekulunda mürəkkəb efir qrupu var. Deməli, lavsan mürəkkəb efirlərə aid olan iri molekullu birləşmədir.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №80'),
  ('KIM-0111', 'Üzvi kimya', 'Alkenlər və alkadienlər', 'qapali', '$\mathrm{C_{n}H_{2n-2}}$ $\mathrm{+2H_{2},}$ t, kat. → X X molekulunda atomların ümumi sayını hesablayın.', NULL::text, '{"A": "2n+2", "B": "3n", "C": "3n+2", "D": "3n–2", "E": "2n–2"}', 'C', '3', '$\mathrm{C_{n}H_{2n-2}}$ $\mathrm{+2H_{2},}$ t, kat. → CnH2n+2 X $\mathrm{-C_{n}H_{2n+2}}$ tərkibli karbohidrogendir. Onun molekulunda atomların ümumi sayı ( n+2n+2 =3n+2) 3n+2 cəmindən ibarətdir.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №81'),
  ('KIM-0112', 'Ümumi kimya', 'Reaksiya sürəti və kimyəvi tarazlıq', 'qapali', 'Temperaturun artması ilə reaksiyanın getmə müddəti 3 dəfə azalarsa, kimyəvi reaksiyanın sürəti necə dəyişər?', NULL::text, '{"A": "dəyişməz", "B": "3 dəfə azalar", "C": "3 dəfə artar", "D": "9 dəfə artar", "E": "9 dəfə azalar"}', 'C', '3', 'Bildiyimiz kimi, $\mathrm{\upsilon _{t2/}\upsilon _{t1=}\tau _{1/}\tau _{2}}$ Buna görə, reaksiyanın sürəti getmə müddəti 3 dəfə azalarsa, sürəti 3 dəfə artar', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №82'),
  ('KIM-0113', 'Üzvi kimya', 'Alkanlar', 'aciq_eded', '15 q alkanın tam yanmasından 44 q karbon $\mathrm{(IV)}$ oksid ayrılmışsa, reaksiyadan neçə qram su alınar? $\mathrm{A_{r}(C)=12,}$ $\mathrm{A_{r}(H)=1,}$ $\mathrm{A_{r}(O)=16}$', NULL::text, NULL::text, '27', '3', 'Molekulunda n sayda karbon atomu olan alkanın bir molunun tam yanma tənliyi aşağıdakı kimidir. CnH2n+2 + 3 → 1 2 n $\mathrm{+\cdot O_{2}}$ $\mathrm{nCO_{2} + (n+1)H_{2}O}$ Reaksiya tənliyinə əsasən uyğun hesablamaları aparaq 14n+2 q alkan ---------------44n q $\mathrm{CO_{2}}$ 15 q alkan -----------------44 q $\mathrm{CO_{2}}$ n=2 deməli alkan $\mathrm{C_{2}H_{6}}$ dır. 15 q etanın tam yanmasından alınan suyun kütləsini (q) hesablayaq $\mathrm{C_{2}H_{6} \rightarrow 3H_{2}O}$ 30 q $\mathrm{C_{2}H_{6}-----------54}$ q $\mathrm{H_{2}O}$ 15 q $\mathrm{C_{2}H_{6}------------x}$ q $\mathrm{H_{2}O}$ x=27', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №83'),
  ('KIM-0115', 'Ümumi kimya', 'Kimyanın əsas anlayışları', 'aciq_eded', '$\mathrm{C_{x}H_{y}O_{z}+}$ $\mathrm{4O_{2} \rightarrow 3CO_{2}+}$ $\mathrm{4H_{2}O}$ tənliyinə əsasən $\mathrm{C_{x}H_{y}O_{z}}$-in 1 molekulunda neçə atom var?', NULL::text, NULL::text, '13', '3', '$\mathrm{C_{x}H_{y}O_{z}+}$ $\mathrm{4O_{2} \rightarrow 3CO_{2}+}$ $\mathrm{4H_{2}O}$ reaksiya tənliyinin əmsallaşdırılmış formasından aydın olur ki, $\mathrm{C_{x}H_{y}O_{z}}$ maddəsinin molekulunda 3 karbon, 8 hidrogen və 2 oksigen atomu var.', '{1}', '2025', '2025-07-13 qəbul, I qrup, A variantı №85')
       ) as v(code, section, topic, type, body, image_path, options, correct, difficulty, solution,
              groups, year, source_ref)
  join subjects s on s.slug = 'kimya'
  join topics sec on sec.subject_id = s.id and sec.parent_id is null and sec.name = v.section
  join topics t on t.subject_id = s.id and t.parent_id = sec.id and t.name = v.topic
on conflict (code) do update set
  topic_id = excluded.topic_id, type = excluded.type, body = excluded.body, image_path = excluded.image_path,
  options = excluded.options, correct_answer = excluded.correct_answer, difficulty = excluded.difficulty,
  solution = excluded.solution, exam_levels = excluded.exam_levels, groups = excluded.groups,
  year = excluded.year, source = excluded.source, source_ref = excluded.source_ref,
  is_active = excluded.is_active;

-- 4) every approved question must now exist (a missing topic would silently drop a row from the join)
do $$
declare n integer;
begin
  select count(*) into n from questions where code in ('KIM-0007', 'KIM-0008', 'KIM-0011', 'KIM-0014', 'KIM-0015', 'KIM-0018', 'KIM-0023', 'KIM-0024', 'KIM-0032', 'KIM-0036', 'KIM-0037', 'KIM-0039', 'KIM-0040', 'KIM-0042', 'KIM-0061', 'KIM-0064', 'KIM-0068', 'KIM-0080', 'KIM-0081', 'KIM-0083', 'KIM-0084', 'KIM-0086', 'KIM-0092', 'KIM-0098', 'KIM-0099', 'KIM-0100', 'KIM-0106', 'KIM-0110', 'KIM-0111', 'KIM-0112', 'KIM-0113', 'KIM-0115');
  if n <> 32 then
    raise exception 'Gözlənilən 32 sual, bazada % tapıldı: geri alınır', n;
  end if;
end $$;

commit;

-- 5) result
select s.name as fenn, count(*) as sual_sayi
  from questions q
  join topics t on t.id = q.topic_id
  join subjects s on s.id = t.subject_id
 where s.slug = 'kimya' and q.source = 'DİM'
 group by s.name;
